PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS observations(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), recorded_at TEXT DEFAULT CURRENT_TIMESTAMP, insulin_index REAL NOT NULL, glucagon_index REAL NOT NULL, note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), recorded_at TEXT DEFAULT CURRENT_TIMESTAMP, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_profiles(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), recorded_at TEXT DEFAULT CURRENT_TIMESTAMP, observation_id INTEGER NOT NULL REFERENCES observations(id), insulin_index REAL NOT NULL, glucagon_index REAL NOT NULL, evidence TEXT NOT NULL, UNIQUE(user_id, observation_id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), recorded_at TEXT DEFAULT CURRENT_TIMESTAMP, event TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS simulation_runs(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), recorded_at TEXT DEFAULT CURRENT_TIMESTAMP, label TEXT NOT NULL, summary TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS simulation_graphs(run_id INTEGER PRIMARY KEY REFERENCES simulation_runs(id) ON DELETE CASCADE, png BLOB NOT NULL);
